CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "8b32109d-1521-469b-80aa-b273da3e8ddb",
  "snapshot_timestamp": "2026-05-22T00:57:11Z",
  "ticket_id": "bf53-e015",
  "items": [
    {
      "original_text": "A shared bug report template exists at plugins/dso/skills/shared/prompts/bug-report-template.md with required sections (Expected Behavior, Actual Behavior) and optional sections (Technical Environment, Action History and Workarounds, Logs, Additional Details)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable artifact and its structural properties that persist as an ongoing system capability after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The Logs section includes guidance to truncate at 30K characters and use ticket comments for overflow",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior and documented guideline for how the Logs section should function"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The template specifies a structured title format: [Component]: [Condition] -> [Observed Result] with the component hierarchy (Tool/Skill -> File/Path -> Logical Workflow)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable property of the template system that persists after implementation, specifying an ongoing structured format requirement"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The ticket CLI auto-converts unicode arrow (U+2192) to ASCII -> in titles on create and edit, eliminating unicode compatibility issues with Jira",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior (auto-conversion) that persists after implementation, making it a durable property of the CLI"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Post-creation validation prints a warning to stderr (exit code 0) when the title does not match the [Component]: [Condition] -> [Observed Result] pattern, directing the agent to edit the title via the ticket edit command",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where validation warnings are printed during post-creation, not a one-time completion task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Post-creation validation prints a separate warning to stderr (exit code 0) when the description is missing Expected Behavior or Actual Behavior headers (case-insensitive check), directing the agent to edit the description via the ticket edit command",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (validation printing warnings) that persists after implementation, even though it involves a specific check and output mechanism"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Post-creation validation prints a warning to stderr (exit code 0) when the description exceeds 30K characters, directing the agent to move excess content to ticket comments",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes an ongoing system behavior that validates and warns on post-creation, persisting after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Bugs are always created regardless of format compliance \u2014 warnings never block creation and exit code is always 0",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes durable system behavior where bug creation and exit codes operate consistently regardless of format validation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The title pattern warning is configurable via dso-config.conf (key: bug_report.title_warning_enabled, default: true) so projects with different title conventions can opt out",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system capability where configuration controls title pattern warning behavior"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "A lightweight /dso:create-bug skill exists that references the template and the correct ticket command; the skill does not add --tags CLI_user by default (only the calling agent knows whether the user explicitly requested the bug). This is a reference skill (guidance doc), not a behavioral skill \u2014 no eval scaffold required.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system property\u2014the existence and correct behavior of a skill\u2014that will remain true after completion"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Using-dso guidance (in the project using-dso doc, to be created by epic dso-khl2 or added inline if not yet available) instructs agents to use the template when creating bugs",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable property of the documentation system where guidance exists and is available for ongoing use by agents"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "An integration test creates a ticket with a non-conforming title and a description missing required headers, and asserts that warnings are emitted to stderr, exit code is 0, and the ticket is persisted \u2014 validating the end-to-end create-and-warn flow",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (create-and-warn flow with specific error handling) that persists after implementation, not a one-time migration task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "A smoke test invokes the /dso:create-bug skill with a realistic bug scenario and asserts the generated ticket description contains Expected Behavior and Actual Behavior headers \u2014 validates the guidance layer produces template-conformant output",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time validation task (smoke test execution and assertion) rather than an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    },
    {
      "original_text": "An actionable remediation test creates a ticket without required headers, captures stderr warning text, and asserts the warning includes (a) the ticket edit command syntax, (b) the specific missing header names, and (c) the path to the bug report template \u2014 confirming warnings provide complete remediation guidance",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where warnings persistently provide complete remediation guidance with specific components, not a one-time test execution"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
